import { createRequire as createLoader, isBuiltin } from "node:module";

const load = createLoader(import.meta.url);
const path = load("node:path");
const config = load("./config.json");
const inline = createLoader(import.meta.url)("./config.json");

function shadow(load) {
  return load + "!";
}

export function describe() {
  return [path.join("a", "b"), config.port, inline.port, isBuiltin("node:path"), load.resolve("node:path"), load.resolve.paths("node:path") === null, shadow("local")].join(":");
}
